function mh(string $value):string{return htmlspecialchars($value,ENT_QUOTES,'UTF-8');}
function mailDecodeHeader(string $value):string{
    if($value===''||!function_exists('imap_mime_header_decode'))return $value;
    $out='';foreach(imap_mime_header_decode($value) as $part){$charset=strtoupper((string)$part->charset);$text=(string)$part->text;if($charset!==''&&$charset!=='DEFAULT'&&$charset!=='UTF-8'){$converted=@mb_convert_encoding($text,'UTF-8',$charset);if($converted!==false)$text=$converted;}$out.=$text;}return trim($out);
}
function mailAddressList(mixed $list):string{
    if(!is_array($list))return '';$values=[];foreach($list as $address){$mailbox=(string)($address->mailbox??'');$host=(string)($address->host??'');$email=$mailbox!==''&&$host!==''?$mailbox.'@'.$host:'';$name=mailDecodeHeader((string)($address->personal??''));$value=trim($name.($email!==''?' <'.$email.'>':''));if($value!=='')$values[]=$value;}return implode(', ',$values);
