function mailDecodeBody(string $text,int $encoding):string{return match($encoding){3=>(string)(base64_decode($text,true)?:''),4=>quoted_printable_decode($text),default=>$text};}
function mailParameter(object $part,string $attribute):string{
    foreach(['dparameters','parameters'] as $property)foreach((array)($part->{$property}??[]) as $parameter)if(strtolower((string)($parameter->attribute??''))===strtolower($attribute))return mailDecodeHeader((string)($parameter->value??''));return '';
}
function mailExtractParts($mailbox,int $messageNumber,object $part,string $section,array &$plain,array &$html,array &$attachments):void{
    $filename=mailParameter($part,'filename')?:mailParameter($part,'name');if($filename!=='')$attachments[$filename]=true;
    if(isset($part->parts)&&is_array($part->parts)){foreach($part->parts as $index=>$child)mailExtractParts($mailbox,$messageNumber,$child,$section===''?(string)($index+1):$section.'.'.($index+1),$plain,$html,$attachments);return;}
    if((int)($part->type??-1)!==0||$filename!=='')return;
    $raw=$section===''?imap_body($mailbox,$messageNumber,FT_PEEK):imap_fetchbody($mailbox,$messageNumber,$section,FT_PEEK);
    $text=mailDecodeBody((string)$raw,(int)($part->encoding??0));$charset=mailParameter($part,'charset');if($charset!==''&&strtoupper($charset)!=='UTF-8'){$converted=@mb_convert_encoding($text,'UTF-8',$charset);if($converted!==false)$text=$converted;}
    $subtype=strtoupper((string)($part->subtype??'PLAIN'));if($subtype==='HTML')$html[]=$text;else $plain[]=$text;
}
function mailMailboxSpec(array $account,string $folder='INBOX'):string{
    $security=(string)$account['ImapSecurity']==='starttls'?'/tls':'/ssl';
    return '{'.(string)$account['ImapHost'].':'.(int)$account['ImapPort'].'/imap'.$security.'/readonly}'.$folder;
}
function mailSyncAccount(PDO $pdo,array $account,string $password,int $offset=0,int $limit=25,int $recentDays=0):array{
    if(!function_exists('imap_open'))throw new RuntimeException('De PHP IMAP-extensie is op deze server niet actief. Activeer die eerst in STRATO of via de PHP-configuratie.');
    @set_time_limit(300);$user=(string)$account['Username'];$inbox=mailMailboxSpec($account);
    $mailbox=@imap_open($inbox,$user,$password,OP_READONLY,1);if($mailbox===false)throw new RuntimeException('Aanmelden bij de mailbox is mislukt. Controleer gebruikersnaam, wachtwoord en IMAP-instellingen.');
