    $listed=@imap_list($mailbox,$reference,'*');imap_close($mailbox);$folders=$listed?:[$reference.'INBOX'];$saved=0;$failed=0;$total=0;$position=0;
    $sql='INSERT INTO EmailBerichten (EmailAccountID,FolderName,FolderHash,UidValidity,MessageUid,MessageId,Subject,Sender,Recipients,SentAt,BodyText,AttachmentNames,IndexedAt) VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?) ON DUPLICATE KEY UPDATE MessageId=VALUES(MessageId),Subject=VALUES(Subject),Sender=VALUES(Sender),Recipients=VALUES(Recipients),SentAt=VALUES(SentAt),BodyText=VALUES(BodyText),AttachmentNames=VALUES(AttachmentNames),IndexedAt=VALUES(IndexedAt)';$save=$pdo->prepare($sql);
    foreach($folders as $listedFolder){$rawFolder=substr((string)$listedFolder,strlen($reference));$display=function_exists('imap_utf7_decode')?imap_utf7_decode($rawFolder):$rawFolder;$mailbox=@imap_open(mailMailboxSpec($account,$rawFolder),$user,$password,OP_READONLY,1);if($mailbox===false){$failed++;continue;}$status=@imap_status($mailbox,mailMailboxSpec($account,$rawFolder),SA_UIDVALIDITY);$uidValidity=(int)($status->uidvalidity??0);$criterion=$recentDays>0?'SINCE "'.date('d-M-Y',strtotime('-'.$recentDays.' days')).'"':'ALL';$uids=@imap_search($mailbox,$criterion,SE_UID)?:[];if(count($uids)>10000)$uids=array_slice($uids,-10000);$total+=count($uids);
        foreach($uids as $uid){$current=$position++;if($current<$offset||$current>=$offset+$limit)continue;try{$number=(int)imap_msgno($mailbox,(int)$uid);if($number<1)continue;$header=imap_headerinfo($mailbox,$number);$structure=imap_fetchstructure($mailbox,$number);if(!$header||!$structure)throw new RuntimeException('E-mailbericht kon niet worden gelezen.');$plain=[];$html=[];$attachments=[];mailExtractParts($mailbox,$number,$structure,'',$plain,$html,$attachments);$body=$plain?implode("\n",$plain):strip_tags(implode("\n",$html));$body=str_replace(["\r\n","\r"],"\n",trim($body));$body=preg_replace('/[ \t]+/u',' ',$body)??'';$body=preg_replace('/\n{3,}/u',"\n\n",$body)??'';$body=mb_substr($body,0,2000000);$sender=mailAddressList($header->from??[]);$recipients=implode(', ',array_filter([mailAddressList($header->to??[]),mailAddressList($header->cc??[]),mailAddressList($header->bcc??[])]));$sentAt=null;$timestamp=strtotime((string)($header->date??''));if($timestamp!==false)$sentAt=date('Y-m-d H:i:s',$timestamp);$save->execute([(int)$account['EmailAccountID'],(string)$display,hash('sha256',$rawFolder),$uidValidity,(int)$uid,mb_substr(mailDecodeHeader((string)($header->message_id??'')),0,500),mb_substr(mailDecodeHeader((string)($header->subject??'(geen onderwerp)')),0,998),mb_substr($sender,0,998),$recipients,$sentAt,$body,implode(', ',array_keys($attachments)),date('Y-m-d H:i:s')]);$saved++;}catch(Throwable $ignored){$failed++;}}
        imap_close($mailbox);
