$id=filter_input(INPUT_GET,'account',FILTER_VALIDATE_INT)?:filter_input(INPUT_POST,'account',FILTER_VALIDATE_INT);$account=null;
if($id)try{$stmt=$pdo->prepare('SELECT * FROM EmailAccounts WHERE EmailAccountID=?');$stmt->execute([$id]);$account=$stmt->fetch(PDO::FETCH_ASSOC)?:null;}catch(Throwable $e){securityIncident($e);$error='Het e-mailaccount kon niet worden geladen.';}
