$hasPassword=$account&&mailPassword($account)!==null;$indexReady=false;$indexed=0;$lastIndexed='';try{$indexReady=(int)$pdo->query("SELECT COUNT(*) FROM information_schema.TABLES WHERE TABLE_SCHEMA=DATABASE() AND TABLE_NAME='EmailBerichten'")->fetchColumn()===1;if($indexReady&&$account){$stmt=$pdo->prepare('SELECT COUNT(*),MAX(IndexedAt) FROM EmailBerichten WHERE EmailAccountID=?');$stmt->execute([$id]);[$indexed,$lastIndexed]=$stmt->fetch(PDO::FETCH_NUM);}}catch(Throwable $ignored){}
?><!doctype html><html lang="nl"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>E-mail synchroniseren</title><style>body{margin:0;background:#f3f6f9;color:#17202a;font:14px system-ui,-apple-system,Segoe UI,Arial}.top{background:#17202a;color:#fff;padding:14px 24px}.wrap{max-width:900px;margin:24px auto;padding:0 14px}.card{background:#fff;border:1px solid #d7e0e8;border-radius:10px;padding:18px;margin-bottom:14px}.ok,.err,.info{padding:10px;border-radius:7px;margin-bottom:12px}.ok{background:#e9f7ed}.err{background:#fff0f0}.info{background:#fff8e4;border-left:4px solid #e5a51d}.btn{display:inline-block;padding:8px 11px;border:1px solid #bfc8d2;border-radius:7px;background:#fff;color:#17202a;text-decoration:none;cursor:pointer}.btn:disabled{opacity:.55;cursor:wait}.primary{background:#2457a6;color:#fff}.danger{color:#8f2424;border-color:#e5b3b3}.row{display:flex;gap:9px;flex-wrap:wrap;align-items:center}input{min-width:280px;padding:8px;border:1px solid #cbd3dc;border-radius:7px}.progress{display:none;align-items:center;gap:12px;margin-top:14px;padding:12px;border-radius:8px;background:#eaf3ff}.progress.active{display:flex}.spinner{width:26px;height:26px;border:4px solid #bed2ea;border-top-color:#2457a6;border-radius:50%;animation:spin .8s linear infinite;flex:0 0 auto}.progress.done .spinner{animation:none;border-color:#2e9b52;background:#2e9b52;box-shadow:inset 0 0 0 6px #fff}.bar{height:8px;background:#d2dfed;border-radius:8px;overflow:hidden;margin-top:6px;min-width:260px}.bar span{display:block;height:100%;width:0;background:#2457a6;transition:width .25s}@keyframes spin{to{transform:rotate(360deg)}}@media(max-width:600px){input{min-width:0;width:100%}.bar{min-width:160px}}</style></head><body><header class="top"><strong>VvE Beheer · E-mailzoekindex v8.24</strong></header><main class="wrap"><p><a class="btn" href="email_settings.php">← E-mailinstellingen</a></p><?php if($message):?><div class="ok">✓ <?=mh($message)?></div><?php endif;?><?php if($error):?><div class="err">⚠ <?=mh($error)?></div><?php endif;?><?php if($account):?><section class="card"><h1><?=mh((string)$account['Label'])?></h1><p><?=mh((string)$account['Username'])?> via <?=mh((string)$account['ImapHost'])?>:<?=(int)$account['ImapPort']?>. De synchronisatie gebruikt IMAP uitsluitend-lezen.</p><?php if(!$indexReady):?><div class="info">Importeer eerst <strong>migrate_v8_21_email_search.sql</strong> in phpMyAdmin.</div><?php endif;?><p>Lokaal geïndexeerd: <strong id="indexedCount"><?=(int)$indexed?></strong> berichten<?=$lastIndexed?' · laatst '.mh((string)$lastIndexed):''?>.</p><form method="post" class="row"><input type="hidden" name="csrf" value="<?=mh(csrfToken())?>"><input type="hidden" name="account" value="<?=(int)$id?>"><input type="hidden" name="action" value="password"><input type="password" name="password" autocomplete="new-password" placeholder="Mailboxwachtwoord" required><button class="btn primary">Wachtwoord server-lokaal opslaan</button></form><?php if($hasPassword):?><hr><form method="post" class="row" id="syncForm"><input type="hidden" name="csrf" value="<?=mh(csrfToken())?>"><input type="hidden" name="account" value="<?=(int)$id?>"><button class="btn primary" id="syncButton" type="submit" <?=$indexReady?'':'disabled'?>>Mailbox nu synchroniseren</button><button class="btn danger" name="action" value="clear">Wachtwoord wissen</button></form><div class="progress" id="progress" role="status" aria-live="polite"><span class="spinner" aria-hidden="true"></span><div><strong id="progressText">Synchronisatie wordt gestart…</strong><div class="bar"><span id="progressBar"></span></div></div></div><?php endif;?></section><?php endif;?></main><script>
const form=document.getElementById('syncForm');if(form){const button=document.getElementById('syncButton'),box=document.getElementById('progress'),text=document.getElementById('progressText'),bar=document.getElementById('progressBar'),count=document.getElementById('indexedCount');form.addEventListener('submit',async event=>{if(event.submitter!==button)return;event.preventDefault();button.disabled=true;box.classList.remove('done','err');box.classList.add('active');let offset=0,saved=0,failed=0;try{while(true){const data=new FormData(form);data.set('action','sync_batch');data.set('offset',String(offset));const response=await fetch('mail_sync.php?account='+encodeURIComponent(data.get('account')),{method:'POST',credentials:'same-origin',headers:{'X-CSRF-Token':data.get('csrf')},body:data});const payload=await response.json();if(!response.ok||!payload.ok)throw new Error(payload.error||'Synchronisatie mislukt.');if(payload.csrf)form.elements.csrf.value=payload.csrf;saved+=Number(payload.saved||0);failed+=Number(payload.failed||0);offset=Number(payload.next||0);const total=Math.max(Number(payload.total||0),offset),percentage=total?Math.min(100,Math.round(offset/total*100)):100;text.textContent=payload.done?'Synchronisatie voltooid: '+saved+' berichten verwerkt'+(failed?' · '+failed+' overgeslagen':''):offset+' van '+total+' berichten gecontroleerd';bar.style.width=percentage+'%';if(payload.done){count.textContent=String(total);box.classList.add('done');break;}}}catch(error){text.textContent='Synchronisatie gestopt: '+(error.message||String(error));box.classList.add('err');}finally{button.disabled=false;}});}
</script></body></html>
